PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "username" varchar, "role" varchar not null default 'user');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "artikels" ("id" integer primary key autoincrement not null, "title" varchar not null, "author" varchar not null, "category" varchar not null, "status" varchar not null default 'Draft', "published_at" date, "created_at" datetime, "updated_at" datetime, "content" text, "image_path" varchar);
CREATE TABLE IF NOT EXISTS "mitras" ("id" integer primary key autoincrement not null, "name" varchar not null, "logo_path" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "portofolios" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar not null, "image_path" varchar, "created_at" datetime, "updated_at" datetime, "content" text, "client" varchar, "date" date);
CREATE TABLE IF NOT EXISTS "program_kursuses" ("id" integer primary key autoincrement not null, "title" varchar not null, "duration" varchar not null, "price" varchar not null, "badge" varchar, "created_at" datetime, "updated_at" datetime, "image_path" varchar, "features" text, "theme_color" varchar default 'theme-1', "description" text, "price_amount" integer);
CREATE TABLE IF NOT EXISTS "kategori_portofolios" ("id" integer primary key autoincrement not null, "name" varchar not null, "color" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "visitors" ("id" integer primary key autoincrement not null, "ip_address" varchar not null, "visited_date" date not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "activity_logs" ("id" integer primary key autoincrement not null, "type" varchar not null, "title" varchar not null, "description" text, "color" varchar not null default 'blue', "icon" varchar not null default 'fa-info-circle', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "mous" ("id" integer primary key autoincrement not null, "nama_file" varchar not null, "tanggal" date not null, "lokasi" varchar not null, "nama_customer" varchar not null, "pengantar_surat_type" varchar check ("pengantar_surat_type" in ('custom', 'template')) not null default 'custom', "pengantar_surat" text, "ketentuan_type" varchar check ("ketentuan_type" in ('custom', 'template')) not null default 'custom', "ketentuan" text, "grand_total" integer not null default '0', "created_by" varchar, "created_at" datetime, "updated_at" datetime, "nomor_surat" varchar, "perihal" varchar, "lampiran" varchar);
CREATE TABLE IF NOT EXISTS "mou_items" ("id" integer primary key autoincrement not null, "mou_id" integer not null, "spesifikasi" varchar not null, "qty" integer not null default '1', "harga" integer not null default '0', "total" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("mou_id") references "mous"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "external_id" varchar not null, "user_name" varchar not null, "user_email" varchar not null, "user_phone" varchar, "program_kursus_id" integer not null, "amount" integer not null, "status" varchar not null default 'pending', "xendit_invoice_id" varchar, "xendit_invoice_url" varchar, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("program_kursus_id") references "program_kursuses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "mou_sections" ("id" integer primary key autoincrement not null, "mou_id" integer not null, "title" varchar not null, "content" text, "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "images" text, "type" varchar not null default 'text', foreign key("mou_id") references "mous"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "layanans" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "icon" varchar, "badge" varchar, "short_description" text, "price_label" varchar, "price" varchar, "price_period" varchar, "image_path" varchar, "description" text, "features_main" text, "pricing_includes" text, "features_full" text, "whatsapp_message" varchar, "created_at" datetime, "updated_at" datetime, "price_amount" integer);
CREATE TABLE IF NOT EXISTS "layanan_orders" ("id" integer primary key autoincrement not null, "external_id" varchar not null, "user_name" varchar not null, "user_email" varchar not null, "user_phone" varchar, "layanan_id" integer not null, "amount" integer not null, "status" varchar not null default 'pending', "xendit_invoice_id" varchar, "xendit_invoice_url" varchar, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("layanan_id") references "layanans"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "event_orders" ("id" integer primary key autoincrement not null, "external_id" varchar not null, "user_name" varchar not null, "user_email" varchar not null, "user_phone" varchar, "amount" numeric not null default '50000', "status" varchar not null default 'pending', "xendit_invoice_id" varchar, "xendit_invoice_url" varchar, "paid_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "events" ("id" integer primary key autoincrement not null, "type" varchar not null default 'bootcamp', "title" varchar not null, "slug" varchar not null, "description" text, "duration_or_date" varchar, "time" varchar, "price" varchar not null, "original_price" varchar, "price_amount" integer default '0', "badge_text" varchar, "badge_icon" varchar, "badge_color" varchar, "image_path" varchar, "syllabus" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "pkl_profiles" ("id" integer primary key autoincrement not null, "user_id" integer not null, "institution" varchar, "major" varchar, "student_id_number" varchar, "phone_number" varchar, "address" text, "start_date" date, "end_date" date, "status" varchar not null default 'active', "program_id" integer, "mentor_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("program_id") references "program_kursuses"("id") on delete set null, foreign key("mentor_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "pkl_tasks" ("id" integer primary key autoincrement not null, "pkl_profile_id" integer not null, "assigned_by" integer, "title" varchar not null, "description" text, "due_date" date, "status" varchar not null default 'pending', "submission_url" text, "submission_file" varchar, "submission_notes" text, "submitted_at" datetime, "grade" integer, "feedback" text, "created_at" datetime, "updated_at" datetime, foreign key("pkl_profile_id") references "pkl_profiles"("id") on delete cascade, foreign key("assigned_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "pkl_quizzes" ("id" integer primary key autoincrement not null, "pkl_profile_id" integer not null, "title" varchar not null, "score" integer not null default '0', "max_score" integer not null default '100', "quiz_date" date, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("pkl_profile_id") references "pkl_profiles"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "pkl_invoices" ("id" integer primary key autoincrement not null, "pkl_profile_id" integer not null, "invoice_code" varchar not null, "amount" numeric not null default '0', "description" varchar, "status" varchar not null default 'pending', "payment_method" varchar, "proof_file" varchar, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("pkl_profile_id") references "pkl_profiles"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "pkl_portfolios" ("id" integer primary key autoincrement not null, "pkl_profile_id" integer not null, "title" varchar not null, "description" text, "thumbnail" varchar, "project_url" varchar, "github_url" varchar, "is_approved" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("pkl_profile_id") references "pkl_profiles"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "pkl_certificates" ("id" integer primary key autoincrement not null, "pkl_profile_id" integer not null, "certificate_number" varchar not null, "predicate" varchar not null default 'Sangat Baik', "issue_date" date, "file_path" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("pkl_profile_id") references "pkl_profiles"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "pkl_histories" ("id" integer primary key autoincrement not null, "pkl_profile_id" integer not null, "activity_type" varchar not null default 'general', "title" varchar not null, "description" text, "icon" varchar not null default 'fa-history', "logged_at" datetime not null default CURRENT_TIMESTAMP, "created_at" datetime, "updated_at" datetime, foreign key("pkl_profile_id") references "pkl_profiles"("id") on delete cascade);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");
CREATE UNIQUE INDEX "visitors_ip_address_visited_date_unique" on "visitors" ("ip_address", "visited_date");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE UNIQUE INDEX "orders_external_id_unique" on "orders" ("external_id");
CREATE UNIQUE INDEX "layanans_slug_unique" on "layanans" ("slug");
CREATE UNIQUE INDEX "layanan_orders_external_id_unique" on "layanan_orders" ("external_id");
CREATE UNIQUE INDEX "event_orders_external_id_unique" on "event_orders" ("external_id");
CREATE UNIQUE INDEX "events_slug_unique" on "events" ("slug");
CREATE UNIQUE INDEX "pkl_invoices_invoice_code_unique" on "pkl_invoices" ("invoice_code");
CREATE UNIQUE INDEX "pkl_certificates_certificate_number_unique" on "pkl_certificates" ("certificate_number");
PRAGMA writable_schema=OFF;
COMMIT;
