INSERT INTO artikels VALUES(1,'Mengapa Belajar Pemrograman Adalah Investasi Terbaik untuk Masa Depan Anda','Admin Elcoding','Teknologi','Published','2026-06-24','2026-08-19 04:27:18','2026-08-19 04:27:18',unistr('Di era digital yang berkembang dengan sangat pesat, kemampuan pemrograman atau coding telah berubah dari sekadar keahlian teknis khusus menjadi salah satu keterampilan dasar yang paling dicari oleh berbagai industri di seluruh dunia.\u000a\u000aBanyak orang mengira bahwa coding hanya diperuntukkan bagi mereka yang ingin menjadi software engineer atau IT support. Faktanya, pemahaman dasar tentang cara kerja perangkat lunak dan logika pemrograman dapat memberikan keuntungan kompetitif yang besar di hampir setiap bidang karier.'),NULL);
INSERT INTO artikels VALUES(2,'5 Tips Memilih Bootcamp Web Developer yang Tepat','Admin Elcoding','Edukasi','Published','2026-06-20','2026-08-19 04:27:18','2026-08-19 04:27:18',unistr('Memilih bootcamp yang tepat adalah langkah penting. Pastikan Anda mempertimbangkan:\u000a1. Kurikulum yang up to date\u000a2. Mentor yang berpengalaman\u000a3. Fokus pada praktik (project-based)\u000a4. Dukungan penyaluran kerja\u000a5. Fasilitas yang memadai'),NULL);
INSERT INTO artikels VALUES(3,'Mengenal Perbedaan UI dan UX Design untuk Pemula','Tim Kreatif','Desain','Draft','2026-06-18','2026-08-19 04:27:18','2026-08-19 04:27:18','User Interface (UI) dan User Experience (UX) adalah dua hal yang berbeda. UI fokus pada tampilan antarmuka (warna, tombol, tipografi), sedangkan UX berfokus pada kemudahan dan pengalaman pengguna saat menggunakan aplikasi. Keduanya harus berjalan beriringan untuk menciptakan produk digital yang sukses.',NULL);
INSERT INTO artikels VALUES(4,'Kerjasama Pengembangan Sinergis dengan LazizMU','Admin Elcoding','Kerjasama','Published','2026-09-02','2026-09-02 05:02:20','2026-09-02 05:02:19','<p>Elcoding Academy secara resmi menjalin kerjasama pengembangan sinergis dengan LazizMU. Kerjasama ini bertujuan untuk memperkuat ekosistem digital, mempercepat otomatisasi layanan, serta meningkatkan efisiensi tata kelola teknologi informasi secara berkesinambungan.</p><p>Melalui kolaborasi ini, kedua pihak berkomitmen untuk menghadirkan inovasi solusi perangkat lunak yang andal dan tepat guna untuk mendukung berbagai program operasional LazizMU secara optimal.</p>','gambar/artikel/kerjasama-lazizmu.webp');
INSERT INTO artikels VALUES(5,'Training & Pelatihan Website Elrhea','Admin Elcoding','Edukasi','Published','2026-07-22','2026-09-02 05:14:36','2026-09-02 05:14:36','<p><strong>Elcoding Academy</strong> sukses menyelenggarakan program <em>Training &amp; Pelatihan Website Elrhea</em> yang berlangsung pada tanggal 21 hingga 22 Juli 2026 di Semarang.</p><p>Kegiatan pelatihan ini dirancang untuk memberikan pemahaman mendalam serta keterampilan praktis dalam pengolahan, pengelolaan, dan pengoperasian website secara mandiri dan profesional. Peserta dibimbing langsung oleh tim instruktur berpengalaman dari Elcoding Academy.</p><p style=\"text-align: center; margin: 25px 0;\"><img src=\"/gambar/artikel/training-pelatihan-elrhea-2.webp\" alt=\"Dokumentasi Pelatihan Website Elrhea\" style=\"max-width: 100%; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.1);\" /></p><p>Selama dua hari penuh, peserta antusias mengikuti rangkaian materi mulai dari pengenalan struktur pengelolaan sistem, manajemen konten, hingga otomatisasi serta pemeliharaan keandalan sistem website. Diharapkan pelatihan ini mampu meningkatkan efisiensi dan kapasitas digital secara berkelanjutan.</p>','gambar/artikel/training-pelatihan-elrhea-1.webp');
